select cron.schedule('studio-daily-recovery','18 7 * * *',$backup$ select net.http_post(url:='https://sfheqjnxlkygjfohoybo.supabase.co/functions/v1/studio-recovery',headers:=jsonb_build_object('Content-Type','application/json','x-studio-worker',(select decrypted_secret from vault.decrypted_secrets where name='studio_worker_token')),body:='{}',timeout_milliseconds:=110000) as request_id where not exists(select 1 from studio_migration.recovery_receipts where verified_at>=date_trunc('day',now())); $backup$);
